package local.blackmamba.vpn;
import android.content.Context;import android.net.*;import android.os.ParcelFileDescriptor;import io.nekohasekai.libbox.*;import java.io.*;import java.util.*;
/** No TUN, no process-wide binding: each probe socket uses the captured physical network. */
final class ProbePlatform implements PlatformInterface {
 final Network network;final ConnectivityManager cm;ProbePlatform(Context c,Network n){network=n;cm=c.getSystemService(ConnectivityManager.class);}
 public boolean usePlatformAutoDetectInterfaceControl(){return true;}
 public void autoDetectInterfaceControl(int fd)throws Exception{TunnelService vpn=TunnelService.instance;if(vpn!=null&&!vpn.protect(fd))throw new IOException("Cannot protect probe socket");try(ParcelFileDescriptor duplicate=ParcelFileDescriptor.fromFd(fd)){network.bindSocket(duplicate.getFileDescriptor());}}
 public int openTun(TunOptions options)throws Exception{throw new IOException("Probe cannot open a VPN tunnel");}
 public boolean useProcFS(){return false;}public int findConnectionOwner(int p,String s,int sp,String d,int dp){return -1;}
 public String packageNameByUid(int uid){return "";}public int uidByPackageName(String name){return -1;}
 public void startDefaultInterfaceMonitor(InterfaceUpdateListener l)throws Exception{LinkProperties p=cm.getLinkProperties(network);String name=p==null?"":p.getInterfaceName();java.net.NetworkInterface ni=name==null||name.isEmpty()?null:java.net.NetworkInterface.getByName(name);NetworkCapabilities caps=cm.getNetworkCapabilities(network);l.updateDefaultInterface(name==null?"":name,ni==null?-1:ni.getIndex(),caps!=null&&caps.hasTransport(NetworkCapabilities.TRANSPORT_CELLULAR),false);}public void closeDefaultInterfaceMonitor(InterfaceUpdateListener l){}
 @Override public NetworkInterfaceIterator getInterfaces()throws Exception {List<io.nekohasekai.libbox.NetworkInterface> list=new ArrayList<>();for(Network n:new Network[]{network}){NetworkCapabilities c=cm.getNetworkCapabilities(n);LinkProperties lp=cm.getLinkProperties(n);if(c==null||lp==null||c.hasTransport(NetworkCapabilities.TRANSPORT_VPN))continue;java.net.NetworkInterface ni=java.net.NetworkInterface.getByName(lp.getInterfaceName());if(ni==null)continue;io.nekohasekai.libbox.NetworkInterface x=new io.nekohasekai.libbox.NetworkInterface();x.setName(ni.getName());x.setIndex(ni.getIndex());x.setMTU(ni.getMTU());x.setFlags(1|64|(ni.isLoopback()?8:0)|(ni.isPointToPoint()?16:0)|(ni.supportsMulticast()?4096:0));x.setType(c.hasTransport(NetworkCapabilities.TRANSPORT_WIFI)?Libbox.InterfaceTypeWIFI:c.hasTransport(NetworkCapabilities.TRANSPORT_CELLULAR)?Libbox.InterfaceTypeCellular:Libbox.InterfaceTypeEthernet);x.setMetered(!c.hasCapability(NetworkCapabilities.NET_CAPABILITY_NOT_METERED));List<String> ips=new ArrayList<>(),dns=new ArrayList<>();for(LinkAddress a:lp.getLinkAddresses())ips.add(a.toString());for(java.net.InetAddress a:lp.getDnsServers())dns.add(a.getHostAddress());x.setAddresses(TunnelService.strings(ips));x.setDNSServer(TunnelService.strings(dns));list.add(x);}return new NetworkInterfaceIterator(){Iterator<io.nekohasekai.libbox.NetworkInterface> it=list.iterator();public boolean hasNext(){return it.hasNext();}public io.nekohasekai.libbox.NetworkInterface next(){return it.next();}};}
 public LocalDNSTransport localDNSTransport(){return new PlatformDns(()->network);}public void writeLog(String text){NetworkErrors.record("probe-core","",text);}public boolean underNetworkExtension(){return false;}public boolean includeAllNetworks(){return false;}
 public WIFIState readWIFIState(){return Libbox.newWIFIState("","");}public StringIterator systemCertificates(){return TunnelService.strings(Collections.emptyList());}public void clearDNSCache(){}public void sendNotification(io.nekohasekai.libbox.Notification n){}
}
